"""Persistent event cards use the existing page's in-memory authenticated session."""
PANEL="""<article class="glass"><h2>Сохранённые события</h2><p class="muted">Находки сохраняются на диске и индексируются без открытой страницы. Привязка сообщений хоста по времени приёма — не доказательство причины.</p><div class="row"><select id="events-kind" aria-label="Тип события"><option value="all">Все события</option><option value="panic">Kernel panic</option><option value="oops">Oops</option><option value="bug">BUG</option><option value="sanitizer">Санитайзеры</option><option value="lockup">Зависания</option><option value="warning">Предупреждения</option><option value="executor_error">Ошибки исполнителя</option></select><button id="events-refresh">Обновить события</button><button id="events-older">Более ранние</button><span id="events-state"></span></div><div id="event-list"></div><h3>Контекст и история повторов</h3><div id="event-detail"></div></article>""".encode('utf-8')
SCRIPT="""'use strict';
(()=>{const names={panic:'Kernel panic',oops:'Oops',bug:'BUG',sanitizer:'Отчёт санитайзера',lockup:'Зависание ядра',warning:'Предупреждение',executor_error:'Ошибка исполнителя'};let seen=-1,selected='',before=null,next=null,working=false,opened=null;
function reset(){el('event-list').replaceChildren();el('event-detail').replaceChildren();el('events-state').textContent='';selected='';before=next=null;opened=null;}
async function detail(campaign,event){const generation=epoch;try{const value=await api('/api/event?'+new URLSearchParams({campaign,event}));if(generation!==epoch||el('campaign').value!==campaign)return;opened={campaign,event};const box=el('event-detail');box.replaceChildren(node('h3',names[value.kind]||value.kind),node('p',value.message),node('p','Связь: '+(value.exact_attempt?'из результата исполнителя':value.ambiguous?'неоднозначная или окно ещё не завершено':'по окну приёма, не причинная')),node('pre',value.context||JSON.stringify(value.executor_result,null,2)));for(const match of value.attempts){const card=node('div','', 'attempt-card');card.append(node('p',match.attempt+(match.pending?' · окно ещё не завершено':'')));const repeat=node('button','Повторить '+match.attempt);repeat.disabled=match.pending||Boolean(state?.busy);repeat.onclick=async()=>{if(state?.busy){el('error').textContent='Дождитесь завершения запуска и анализа';return;}if(!confirm('Повторить сохранённую конфигурацию '+match.attempt+'? Сначала восстановите хост. Связь по времени не доказывает причину.'))return;try{await api('/api/replay-event',{campaign,event,attempt:match.attempt});await refresh();}catch(e){el('error').textContent=e.message;}};card.append(repeat);for(const name of ['config.json','result.json','executor.log']){const b=node('button',name);b.onclick=()=>download(file(campaign,match.attempt,name),campaign+'-'+match.attempt+'-'+name);card.append(b);}box.append(card);}if(!value.attempts.length)box.append(node('p','Связанная попытка не установлена. Индекс может ещё дополняться; не выбирайте случайную попытку.','muted'));const save=node('button','Скачать событие с контекстом');save.onclick=()=>download('/api/event-download?'+new URLSearchParams({campaign,event}),campaign+'-'+event+'.json');box.append(save,node('h3','Повторы этого события'));for(const row of value.repeat_results){const card=node('div','', 'attempt-card');card.append(node('p',row.campaign),node('p',!row.result?'Итоговый файл ещё не создан':row.result.execution_error?'Ошибка повторного исполнения: '+row.result.execution_error:row.result.analysis_error?'Ошибка анализа повтора: '+row.result.analysis_error:'Результат повтора сохранён; воспроизведение сбоя автоматически не подтверждено'));if(row.result)card.append(node('pre',JSON.stringify(row.result,null,2)));const b=node('button','Открыть журналы повтора');b.onclick=()=>{const id=row.campaign;if(![...el('campaign').options].some(o=>o.value===id)){const o=node('option',id);o.value=id;el('campaign').append(o);}el('campaign').value=id;refresh();document.querySelector('[data-tab="logs"]').click();};card.append(b);box.append(card);}if(!value.repeat_results.length)box.append(node('p','Повторов пока нет.','muted'));}catch(e){if(generation!==epoch)reset();else el('events-state').textContent=e.message;}}
async function update(force=false){if(seen!==epoch){seen=epoch;reset();}if(!token){reset();return;}if(working)return;const campaign=el('campaign').value;if(!campaign)return;if(selected!==campaign){reset();selected=campaign;}working=true;const generation=epoch;try{const q={campaign,limit:'100',kind:el('events-kind').value};if(before)q.before=String(before);const value=await api('/api/events?'+new URLSearchParams(q));if(generation!==epoch||el('campaign').value!==campaign||el('events-kind').value!==q.kind)return;next=value.next_before;el('events-state').textContent='Сохранено: '+value.count+' · проиндексировано байтов: '+value.indexed_bytes+(value.index_error?' · ошибка: '+value.index_error:' · индекс дополняется в фоне')+(value.long_lines_prefix_only?' · длинные строки: поиск по первым 8192 байтам':'');el('events-older').disabled=!next;el('event-list').replaceChildren();for(const event of value.events){const card=node('article','', 'attempt-card '+(event.kind==='warning'?'warning':'critical'));card.append(node('h3',names[event.kind]||event.kind),node('p',event.message),node('p',event.exact_attempt?'Попытка: '+event.exact_attempt:event.attempts.length?'Кандидаты: '+event.attempts.map(a=>a.attempt+(a.pending?' (ожидание окна)':'')).join(', '):'Связь с попыткой пока не установлена'));const b=node('button','Контекст, повтор и результаты');b.onclick=()=>detail(campaign,event.id);card.append(b);el('event-list').append(card);}if(!value.events.length)el('event-list').append(node('p','Событий на этой странице пока нет. Это не подтверждает отсутствие ошибок: проверьте прогресс индекса и канал захвата.','muted'));if(force&&opened)await detail(opened.campaign,opened.event);}catch(e){if(generation!==epoch)reset();else el('events-state').textContent=e.message;}finally{working=false;}}
el('events-refresh').onclick=()=>update(true);el('events-kind').onchange=()=>{before=next=null;update();};el('events-older').onclick=()=>{if(next){before=next;update();}};for(const id of ['login','logout'])el(id).addEventListener('click',()=>{seen=epoch;reset();});el('campaign').addEventListener('change',()=>{reset();update();});for(const b of document.querySelectorAll('[data-tab]'))b.addEventListener('click',()=>{if(b.dataset.tab==='results')update(true);});setInterval(()=>{if(!token||seen!==epoch){seen=epoch;reset();}if(tab==='results')update();},2000);
})();
""".encode('utf-8')
